detect_download_format <- function(path) { if(!file.exists(path)||file.info(path)$size<4)return("unknown");b<-readBin(path,"raw",n=8);h<-paste(sprintf("%02x",as.integer(b)),collapse=" ");if(length(b)>=8&&identical(h,"89 48 44 46 0d 0a 1a 0a"))return("netcdf4_hdf5");if(length(b)>=4&&identical(substr(h,1,11),"43 44 46 01"))return("netcdf_classic");if(length(b)>=4&&identical(substr(h,1,11),"43 44 46 02"))return("netcdf_classic");if(length(b)>=4&&identical(substr(h,1,11),"50 4b 03 04"))return("zip");if(length(b)>=4&&identical(substr(h,1,11),"47 52 49 42"))return("grib");"unknown" }
.ncatt <- function(nc,varid,name,default=NA) { z<-tryCatch(ncdf4::ncatt_get(nc,varid,name),error=function(e)list(hasatt=FALSE));if(isTRUE(z$hasatt))z$value else default }
decode_netcdf_time <- function(values,units,calendar="standard") { if(is.null(units)||length(units)!=1L||is.na(units)||!nzchar(units))stop("NetCDF time units are missing",call.=FALSE);cal<-tolower(calendar%||%"standard");if(!cal%in%c("standard","gregorian","proleptic_gregorian"))stop("Unsupported NetCDF calendar: ",calendar,call.=FALSE);m<-regexec("^(seconds|hours|days)\\s+since\\s+(.+)$",tolower(trimws(units)));z<-regmatches(tolower(trimws(units)),m)[[1]];if(length(z)!=3)stop("Unsupported NetCDF time units: ",units,call.=FALSE);origin_txt<-sub(" z$","",trimws(z[3]),ignore.case=TRUE);origin_txt<-sub("[.]0+$","",origin_txt);origin<-as.POSIXct(origin_txt,tz="UTC",format="%Y-%m-%d %H:%M:%S");if(is.na(origin))origin<-as.POSIXct(origin_txt,tz="UTC",format="%Y-%m-%d");if(is.na(origin))stop("Could not decode NetCDF time origin: ",origin_txt,call.=FALSE);mult<-c(seconds=1,hours=3600,days=86400)[[z[2]]];as.POSIXct(origin+as.numeric(values)*mult,tz="UTC",origin="1970-01-01") }
inspect_netcdf_ncdf4 <- function(path) { if(!requireNamespace("ncdf4",quietly=TRUE))stop("Package 'ncdf4' is required");nc<-ncdf4::nc_open(path);on.exit(ncdf4::nc_close(nc),add=TRUE);vars<-lapply(nc$var,function(v)list(name=v$name,units=.ncatt(nc,v$name,"units",NA_character_),long_name=.ncatt(nc,v$name,"long_name",NA_character_),standard_name=.ncatt(nc,v$name,"standard_name",NA_character_),dimensions=vapply(v$dim,function(d)d$name,character(1)),dimension_lengths=vapply(v$dim,function(d)d$len,numeric(1)),fill_value=v$missval,missing_value=.ncatt(nc,v$name,"missing_value",NA_real_),scale_factor=.ncatt(nc,v$name,"scale_factor",1),add_offset=.ncatt(nc,v$name,"add_offset",0)));for(d in setdiff(names(nc$dim),names(vars)))vars[[d]]<-list(name=d,units=nc$dim[[d]]$units,dimensions=d,dimension_lengths=nc$dim[[d]]$len,fill_value=NA_real_,missing_value=NA_real_,scale_factor=1,add_offset=0);dims<-lapply(nc$dim,function(d)list(name=d$name,length=d$len,units=d$units,values=if(d$len<=10000)d$vals else NULL));tn<-intersect(c("valid_time","time"),names(nc$dim));tn<-if(length(tn))tn[[1]]else NA_character_;ln<-intersect(c("longitude","lon"),names(nc$dim));ln<-if(length(ln))ln[[1]]else NA_character_;an<-intersect(c("latitude","lat"),names(nc$dim));an<-if(length(an))an[[1]]else NA_character_;tv<-if(!is.na(tn))nc$dim[[tn]]$vals else numeric();tu<-if(!is.na(tn))nc$dim[[tn]]$units else NA_character_;co<-if(!is.na(tn)) .ncatt(nc,tn,"calendar",NULL) else NULL;ce<-if(is.null(co)||length(co)==0L||is.na(co)||!nzchar(co))"standard"else co;decoded<-if(!is.na(tn))decode_netcdf_time(tv,tu,ce)else as.POSIXct(character());lon<-if(!is.na(ln))nc$dim[[ln]]$vals else numeric();lat<-if(!is.na(an))nc$dim[[an]]$vals else numeric();list(path=path,format=detect_download_format(path),variables=vars,dimensions=dims,global_attributes=nc$gatts,coordinate_variables=list(longitude=lon,latitude=lat),longitude_variable=ln,latitude_variable=an,time_variable=tn,time_units=tu,time_values=tv,time_calendar_original=co,time_calendar_effective=ce,time_calendar_source=if(is.null(co)||is.na(co)||!nzchar(co))"default"else"attribute",calendar=ce,decoded_timestamps=decoded,decoded_dates=as.Date(decoded),longitude_range=if(length(lon))range(lon)else numeric(),latitude_range=if(length(lat))range(lat)else numeric(),longitude_order=if(length(lon)>1)if(lon[1]<tail(lon,1))"ascending"else"descending"else"single",latitude_order=if(length(lat)>1)if(lat[1]<tail(lat,1))"ascending"else"descending"else"single") }
select_era5_temperature_variable <- function(nc_metadata) { candidates<-intersect(c("t2m","2m_temperature"),names(nc_metadata$variables));if(length(candidates)!=1L)stop("Could not select an unambiguous ERA5 temperature variable",call.=FALSE);v<-nc_metadata$variables[[candidates[[1]]]];if(!identical(normalize_source_units(v$units),"K"))stop("Selected temperature variable is not in kelvin",call.=FALSE);candidates[[1]] }
read_era5_daily_with_ncdf4 <- function(path,variable="t2m",expected_dates=NULL,variable_spec=NULL) { md<-inspect_netcdf_ncdf4(path);spec<-variable_spec%||%get_variable_spec(variable);selected<-resolve_netcdf_variable(md,spec);v<-md$variables[[selected]];units_original<-v$units;units_normalized<-normalize_source_units(units_original);expected_units<-if(spec$id=="era5_soilmoist")"m3 m-3"else"K";if(!identical(units_normalized,expected_units))stop("Selected variable has incompatible source units: ",units_original,call.=FALSE);dims<-v$dimensions;time_name<-intersect(dims,c("valid_time","time"));time_name<-if(length(time_name))time_name[[1]]else stop("Selected NetCDF variable has no attached time dimension",call.=FALSE);lon_name<-intersect(dims,c("longitude","lon"));lon_name<-if(length(lon_name))lon_name[[1]]else stop("Selected NetCDF variable has no attached longitude dimension",call.=FALSE);lat_name<-intersect(dims,c("latitude","lat"));lat_name<-if(length(lat_name))lat_name[[1]]else stop("Selected NetCDF variable has no attached latitude dimension",call.=FALSE);nc<-ncdf4::nc_open(path);on.exit(ncdf4::nc_close(nc),add=TRUE);lon<-ncdf4::ncvar_get(nc,lon_name);lat<-ncdf4::ncvar_get(nc,lat_name);time<-ncdf4::ncvar_get(nc,time_name);a<-ncdf4::ncvar_get(nc,selected,raw_datavals=TRUE);perm<-match(c(lon_name,lat_name,time_name),dims);if(anyNA(perm)||length(dim(a))!=3L)stop("Selected variable must have longitude, latitude, and time dimensions",call.=FALSE);a<-aperm(a,perm);fill<-c(v$fill_value,v$missing_value);if(length(fill)&&any(is.finite(fill)))a[a%in%fill]<-NA_real_;sf<-as.numeric(v$scale_factor);ao<-as.numeric(v$add_offset);if(!is.na(sf)&&sf!=1)a<-a*sf;if(!is.na(ao)&&ao!=0)a<-a+ao;decoded<-as.Date(decode_netcdf_time(time,md$time_units,md$time_calendar_effective));expected<-normalize_date_vector(expected_dates,"expected_dates");decoded<-normalize_date_vector(decoded,"decoded_dates");expected_keys<-unname(format(expected,"%Y-%m-%d"));decoded_keys<-unname(format(decoded,"%Y-%m-%d"));missing_dates<-setdiff(expected_keys,decoded_keys);extra_dates<-setdiff(decoded_keys,expected_keys);duplicate_decoded_dates<-unique(decoded_keys[duplicated(decoded_keys)]);if(!identical(decoded_keys,expected_keys))stop("Decoded dates do not match expected dates; expected dates=",paste(expected_keys,collapse=","),"; decoded dates=",paste(decoded_keys,collapse=","),"; missing dates=",paste(missing_dates,collapse=","),"; extra dates=",paste(extra_dates,collapse=","),"; duplicate dates=",paste(duplicate_decoded_dates,collapse=","),"; time-coordinate name=",time_name,"; time-coordinate units=",md$time_units,"; raw time-coordinate values=",paste(time,collapse=","),"; calendar=",md$time_calendar_effective,call.=FALSE);source_stats<-if(spec$id=="era5_soilmoist")validate_source_values(a,spec,-0.05,1.05)else list(source_minimum=min(a,na.rm=TRUE),source_maximum=max(a,na.rm=TRUE));dx<-if(length(lon)>1)median(diff(sort(lon)))else 1;dy<-if(length(lat)>1)median(diff(sort(lat)))else 1;ras<-vector("list",length(decoded));for(i in seq_along(decoded)){mm<-t(a[,,i,drop=TRUE]);if(length(lat)>1&&lat[1]<tail(lat,1))mm<-mm[nrow(mm):1,,drop=FALSE];if(length(lon)>1&&lon[1]>tail(lon,1))mm<-mm[,ncol(mm):1,,drop=FALSE];r<-terra::rast(mm,extent=terra::ext(min(lon)-abs(dx)/2,max(lon)+abs(dx)/2,min(lat)-abs(dy)/2,max(lat)+abs(dy)/2),crs="EPSG:4326");if(any(lon<0)&&any(lon>180))r<-terra::rotate(r);ras[[i]]<-convert_source_units(r,spec,units_original)};list(rasters=ras,dates=decoded,reader_used="ncdf4",source_format=md$format,selected_variable=selected,selected_netcdf_variable=selected,selected_variable_alias=selected,data_variable_dimensions=dims,dimension_names=dims,dimension_lengths=unname(v$dimension_lengths),dimension_order=dims,latitude_direction=md$latitude_order,longitude_direction=md$longitude_order,longitude_convention=if(all(lon>=0))"0_360"else"-180_180",time_coordinate_name=time_name,time_coordinate_source="dimension",time_coordinate_units=md$time_units,time_coordinate_raw_values=time,time_coordinate_calendar_original=md$time_calendar_original,time_coordinate_calendar_effective=md$time_calendar_effective,calendar_source=md$time_calendar_source,decoded_dates=decoded,source_units=units_original,source_units_original=units_original,source_units_normalized=units_normalized,output_units=spec$output_units,unit_conversion=spec$unit_conversion,source_value_minimum=source_stats$source_minimum,source_value_maximum=source_stats$source_maximum,metadata=md,temperature_variable=if(spec$id=="era5_mintemp")selected else NULL,variable_spec=spec,daily_statistic_source="cds_daily_statistics",daily_statistic=spec$daily_statistic,subdaily_frequency=spec$frequency) }
read_era5_daily_layers <- function(path,expected_dates=NULL,variable_spec=NULL) {spec<-variable_spec%||%get_variable_spec("era5_mintemp");fmt<-detect_download_format(path);if(fmt%in%c("netcdf4_hdf5","netcdf_classic")){if(fmt=="netcdf4_hdf5")return(read_era5_daily_with_ncdf4(path,expected_dates=expected_dates,variable_spec=spec));x<-tryCatch(terra::rast(path),error=function(e)NULL);if(!is.null(x))return(list(rasters=lapply(seq_len(terra::nlyr(x)),function(i)x[[i]]),dates=normalize_date_vector(terra::time(x)),reader_used="terra",source_format=fmt,selected_variable=spec$netcdf_variable_names[[1]],selected_variable_alias=spec$netcdf_variable_names[[1]],source_units=spec$source_units,source_units_original=spec$source_units,source_units_normalized=normalize_source_units(spec$source_units),output_units=spec$output_units,unit_conversion=spec$unit_conversion,variable_spec=spec));return(read_era5_daily_with_ncdf4(path,expected_dates=expected_dates,variable_spec=spec))};if(fmt=="zip"){ex<-file.path(dirname(path),"extracted");fs::dir_create(ex,recurse=TRUE);normalize_downloaded_file(path,ex);files<-list.files(ex,pattern="\\.nc4?$",full.names=TRUE,recursive=TRUE,ignore.case=TRUE);if(!length(files))stop("ZIP contains no NetCDF files");return(read_era5_daily_layers(files[[1]],expected_dates,spec))};if(fmt=="grib")stop("GRIB dispatch requires a terra/GDAL reader");stop("Unsupported download format: ",fmt," (magic bytes inspected)",call.=FALSE) }
discover_netcdf_files <- function(path){fmt<-detect_download_format(path);if(fmt%in%c("netcdf4_hdf5","netcdf_classic"))return(path);if(fmt=="zip"){z<-utils::unzip(path,list=TRUE)$Name;return(file.path(dirname(path),z[grepl("\\.nc4?$",z,ignore.case=TRUE)]))};character()}
normalize_downloaded_file <- function(path,extraction_dir){if(!file.exists(path))stop("Raw file missing: ",path);if(detect_download_format(path)!="zip")return(discover_netcdf_files(path));fs::dir_create(extraction_dir,recurse=TRUE);z<-utils::unzip(path,list=TRUE)$Name;if(any(grepl("(^|/|\\\\)\\.\\.",z)))stop("Unsafe archive paths");utils::unzip(path,exdir=extraction_dir);list.files(extraction_dir,pattern="\\.nc4?$",full.names=TRUE,recursive=TRUE,ignore.case=TRUE)}
inspect_netcdf_file <- function(path)inspect_netcdf_ncdf4(path)

read_daily_netcdf <- function(path, variable_spec, raw_request_dates, dates_to_process=NULL, request_hash=NULL) {
  md<-inspect_netcdf_ncdf4(path); spec<-variable_spec; selected<-resolve_netcdf_variable(md,spec); v<-md$variables[[selected]]; units_original<-v$units; units_normalized<-normalize_source_units(units_original); expected_units<-if(spec$id=="era5_soilmoist")"m3 m-3"else"K";if(!identical(units_normalized,expected_units))stop("Selected variable has incompatible source units: ",units_original,call.=FALSE)
  dims<-v$dimensions;time_name<-intersect(dims,c("valid_time","time"));time_name<-if(length(time_name))time_name[[1]]else stop("Selected NetCDF variable has no attached time dimension",call.=FALSE);lon_name<-intersect(dims,c("longitude","lon"));lon_name<-if(length(lon_name))lon_name[[1]]else stop("Selected NetCDF variable has no attached longitude dimension",call.=FALSE);lat_name<-intersect(dims,c("latitude","lat"));lat_name<-if(length(lat_name))lat_name[[1]]else stop("Selected NetCDF variable has no attached latitude dimension",call.=FALSE)
  nc<-ncdf4::nc_open(path);on.exit(ncdf4::nc_close(nc),add=TRUE);lon<-ncdf4::ncvar_get(nc,lon_name);lat<-ncdf4::ncvar_get(nc,lat_name);time<-ncdf4::ncvar_get(nc,time_name);a<-ncdf4::ncvar_get(nc,selected,raw_datavals=TRUE);perm<-match(c(lon_name,lat_name,time_name),dims);if(anyNA(perm)||length(dim(a))!=3L)stop("Selected variable must have longitude, latitude, and time dimensions",call.=FALSE);a<-aperm(a,perm);fill<-c(v$fill_value,v$missing_value);if(length(fill)&&any(is.finite(fill)))a[a%in%fill]<-NA_real_;sf<-as.numeric(v$scale_factor);ao<-as.numeric(v$add_offset);if(!is.na(sf)&&sf!=1)a<-a*sf;if(!is.na(ao)&&ao!=0)a<-a+ao
  decoded<-normalize_date_vector(decode_netcdf_time(time,md$time_units,md$time_calendar_effective),"decoded_dates");requested<-normalize_date_vector(raw_request_dates,"raw_request_dates");decoded_keys<-unname(format(decoded,"%Y-%m-%d"));requested_keys<-unname(format(requested,"%Y-%m-%d"));missing_dates<-setdiff(requested_keys,decoded_keys);extra_dates<-setdiff(decoded_keys,requested_keys);duplicate_dates<-unique(decoded_keys[duplicated(decoded_keys)]);if(!identical(decoded_keys,requested_keys))stop("Raw date coverage mismatch; raw_path=",path,"; request_hash=",request_hash %||% "unknown","; raw request dates=",paste(requested_keys,collapse=","),"; decoded raw dates=",paste(decoded_keys,collapse=","),"; dates selected for processing=",paste(format(normalize_date_vector(dates_to_process),"%Y-%m-%d"),collapse=","),"; missing request dates=",paste(missing_dates,collapse=","),"; extra decoded dates=",paste(extra_dates,collapse=","),"; duplicate dates=",paste(duplicate_dates,collapse=","),"; time-coordinate name=",time_name,"; time-coordinate units=",md$time_units,"; raw time-coordinate values=",paste(time,collapse=","),"; calendar=",md$time_calendar_effective,call.=FALSE)
  selected_dates<-if(is.null(dates_to_process)||!length(dates_to_process))requested else normalize_date_vector(dates_to_process,"dates_to_process");selected_keys<-unname(format(selected_dates,"%Y-%m-%d"));if(any(!selected_keys%in%decoded_keys)||anyDuplicated(selected_keys))stop("Selected dates are absent from raw or duplicated; raw_path=",path,"; dates selected for processing=",paste(selected_keys,collapse=","),call.=FALSE);idx<-match(selected_keys,decoded_keys);source_stats<-if(spec$id=="era5_soilmoist")validate_source_values(a,spec,-.05,1.05)else list(source_minimum=min(a,na.rm=TRUE),source_maximum=max(a,na.rm=TRUE));dx<-if(length(lon)>1)median(diff(sort(lon)))else 1;dy<-if(length(lat)>1)median(diff(sort(lat)))else 1;ras<-vector("list",length(idx));for(j in seq_along(idx)){mm<-t(a[,,idx[j],drop=TRUE]);if(length(lat)>1&&lat[1]<tail(lat,1))mm<-mm[nrow(mm):1,,drop=FALSE];if(length(lon)>1&&lon[1]>tail(lon,1))mm<-mm[,ncol(mm):1,,drop=FALSE];r<-terra::rast(mm,extent=terra::ext(min(lon)-abs(dx)/2,max(lon)+abs(dx)/2,min(lat)-abs(dy)/2,max(lat)+abs(dy)/2),crs="EPSG:4326");if(any(lon<0)&&any(lon>180))r<-terra::rotate(r);ras[[j]]<-convert_source_units(r,spec,units_original)};list(rasters=ras,dates=selected_dates,decoded_dates=decoded,reader_used="ncdf4",source_format=md$format,selected_variable=selected,selected_netcdf_variable=selected,selected_variable_alias=selected,data_variable_dimensions=dims,dimension_names=dims,dimension_lengths=unname(v$dimension_lengths),dimension_order=dims,latitude_direction=md$latitude_order,longitude_direction=md$longitude_order,longitude_convention=if(all(lon>=0))"0_360"else"-180_180",time_coordinate_name=time_name,time_coordinate_source="dimension",time_coordinate_units=md$time_units,time_coordinate_raw_values=time,time_coordinate_calendar_original=md$time_calendar_original,time_coordinate_calendar_effective=md$time_calendar_effective,calendar_source=md$time_calendar_source,source_units=units_original,source_units_original=units_original,source_units_normalized=units_normalized,output_units=spec$output_units,unit_conversion=spec$unit_conversion,source_value_minimum=source_stats$source_minimum,source_value_maximum=source_stats$source_maximum,metadata=md,variable_spec=spec,daily_statistic_source="cds_daily_statistics",daily_statistic=spec$daily_statistic,subdaily_frequency=spec$frequency)
}
read_era5_daily_with_ncdf4 <- function(path,variable="t2m",expected_dates=NULL,variable_spec=NULL,raw_request_dates=NULL,dates_to_process=NULL,request_hash=NULL) { spec<-variable_spec%||%get_variable_spec(variable); read_daily_netcdf(path,spec,raw_request_dates%||%expected_dates,dates_to_process%||%raw_request_dates%||%expected_dates,request_hash) }
read_era5_daily_layers <- function(path,expected_dates=NULL,variable_spec=NULL,raw_request_dates=NULL,dates_to_process=NULL,request_hash=NULL) { spec<-variable_spec%||%get_variable_spec("era5_mintemp"); fmt<-detect_download_format(path); if(fmt=="netcdf4_hdf5")return(read_daily_netcdf(path,spec,raw_request_dates%||%expected_dates,dates_to_process%||%raw_request_dates%||%expected_dates,request_hash)); if(fmt=="zip"){ex<-file.path(dirname(path),"extracted");fs::dir_create(ex,recurse=TRUE);normalize_downloaded_file(path,ex);files<-list.files(ex,pattern="\\.nc4?$",full.names=TRUE,recursive=TRUE,ignore.case=TRUE);if(!length(files))stop("ZIP contains no NetCDF files");return(read_era5_daily_layers(files[[1]],expected_dates, spec,raw_request_dates,dates_to_process,request_hash))};stop("Unsupported or non-NetCDF raw format: ",fmt,call.=FALSE) }
